 private restoreRevision(revision:Revision){try{const settings={...defaults,...validateSettings(revision.settings)},record=revision.records?this.validateRecords(revision.records):undefined;if(record){const schedule=validatePreferenceDocument(record.schedule),workspace=validateWorkspace(record.workspace),appearance=validateAppearanceMap(record.appearance),presentation=record.presentation;if(this.extras.school&&!presentation.school){this.notice(this.copy('Unlock the presentation mode before restoring a revision that turns it off.','請先解鎖顯示模式，再還原會關閉模式嘅版本。'),'warning');return}if(typeof presentation.school!=='boolean'||typeof presentation.schoolName!=='string'||presentation.schoolName.length>80||typeof presentation.paletteFull!=='boolean'||!Number.isInteger(presentation.completedSteps))throw Error();localStorage.setItem('material-git-site.schedule.v1',JSON.stringify(schedule));localStorage.setItem('material-git-site.workspace.v1',JSON.stringify(workspace));localStorage.setItem('material-git-site.element-appearance.v1',JSON.stringify(appearance));if(record.converterReceipts)(this.querySelector('mg-site-converter') as BrowserConverter|null)?.restoreReceipts(record.converterReceipts);if(record.notifications){this.notifications=validateNotifications({...record.notifications,revision:this.notifications.revision+1});localStorage.setItem(notificationKey,JSON.stringify(this.notifications))}this.workspaceState=workspace;this.extras={...this.extras,...presentation};const tabs=this.querySelector('mg-site-tabs') as BrowserTabs|null;if(tabs)tabs.workspace=workspace;const schedules=this.querySelector('mg-site-schedules') as BrowserSchedules|null;schedules?.restoreDocument(schedule)}this.settings=settings;this.save('Restored '+revision.label,true,false)}catch{this.notice(this.copy('This revision could not be restored. Check browser storage and the record format.','未能還原呢個版本。請檢查瀏覽器儲存同記錄格式。'),'error','history')}}
