 private notificationStack(){const records=[...visibleNotificationStack(this.notifications,Date.now(),this.currentSettings.lowStimulation),...(this.fallbackNotification?[this.fallbackNotification]:[])];return records.length||this.notificationFailure?html`<mg-site-layout class="notification-stack" aria-label=${this.copy('Current messages','目前訊息')}>${records.map(record=>html`<mg-site-surface class=${'snackbar '+record.category} role=${record.category==='error'?'alert':'status'}><mg-site-layout><strong>${this.copy(...notificationNames[record.category])}</strong><p>${this.playful(record.en,record.yue)}</p><mg-site-layout class="actions"><md-text-button @click=${()=>{if(record===this.fallbackNotification)this.fallbackNotification=null;else this.changeNoticeRecords({revision:this.notifications.revision,ids:[record.id],dismissed:true})}}>${this.copy('Dismiss','關閉')}</md-text-button>${record.action?html`<md-text-button @click=${()=>this.notificationAction(record.action!)}>${record.action==='latest-release'||record.action==='release-notes'?this.copy('Retry','重試'):this.copy('Open recovery control','開啟恢復控制')}</md-text-button>`:nothing}<md-text-button @click=${()=>this.openNoticeCenter()}>${this.copy('All messages','全部訊息')} (${this.notifications.records.length})</md-text-button></mg-site-layout></mg-site-layout></mg-site-surface>`)}${this.notificationFailure?html`<mg-site-surface class="snackbar notification-storage-warning" role="alert"><p>${this.notificationFailure}</p><md-text-button @click=${()=>this.openNoticeCenter()}>${this.copy('Open messages','開啟訊息')}</md-text-button></mg-site-surface>`:nothing}</mg-site-layout>`:nothing}

